def words_in_sentence(sentence):
    # Split the sentence into a list of words
    words = sentence.split()

    # Create an empty string to store the prime word lengths
    prime_words = ""

    # Iterate over the words in the sentence
    for word in words:
        # Check if the length of the word is prime
        if is_prime(len(word)):
            # If it is, add it to the list of prime words
            prime_words += word + " "

    return prime_words.strip()

def is_prime(n):
    # Check if n is a prime number by iterating from 2 to n-1
    for i in range(2, n):
        if n % i == 0:
            return False
    return True
