def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into individual letters
    letters = test.split()

    # Create an empty dictionary to store the letter counts
    letter_counts = {}

    # Iterate over the letters and increment the count for each one
    for letter in letters:
        if letter not in letter_counts:
            letter_counts[letter] = 1
        else:
            letter_counts[letter] += 1

    # Find the most frequent letter and its count
    max_count = -1
    most_frequent_letters = []
    for letter, count in letter_counts.items():
        if count > max_count:
            max_count = count
            most_frequent_letters = [letter]
        elif count == max_count:
            most_frequent_letters.append(letter)

    # Return the dictionary with the most frequent letter and its count
    return {most_frequent_letters[0]: max_count} if len(most_frequent_letters) == 1 else {most_frequent_letters[i]: max_count for i in range(len(most_frequent_letters))}
```
